 private function definitions():array{
  $memberVars=['user'=>'Brugernavn','mention'=>'Nævner medlemmet','username'=>'Discord-brugernavn','display_name'=>'Visningsnavn','user_id'=>'Discord bruger-ID','avatar'=>'Avatar URL','server'=>'Servernavn','server_id'=>'Discord server-ID','member_count'=>'Antal medlemmer','member_number'=>'Medlemmets nummer','created_at'=>'Konto oprettet','joined_at'=>'Dato medlemmet joinede','account_age'=>'Kontoens alder','role_count'=>'Antal roller','date'=>'Dato','time'=>'Tid'];
  $core=[
